    },
    {
      "offset": 18,
      "meaning": "uint16 calibration field copied from hash entry offset 20"
    },
    {
      "offset": 20,
      "meaning": "uint16 calibration field copied from hash entry offset 22"
    },
    {
      "offset": 22,
      "meaning": "conditional uint16 field copied from hash entry offset 24 when cal_flags bit 3 is set"
    },
    {
      "offset": 24,
      "meaning": "conditional uint16 field copied from hash entry offset 26 when cal_flags bit 3 is set"
    },
    {
      "offset": 26,
      "meaning": "conditional uint16 field copied from data following the optional header fields"
    },
    {
      "offset": 28,
      "meaning": "conditional uint16 field copied from data following the optional header fields"
    }
  ]
}
